CREATE TABLE IF NOT EXISTS geo_nonces (nonce TEXT PRIMARY KEY, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS geo_runs (environment TEXT NOT NULL, client_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_id TEXT NOT NULL, action_count INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(environment,client_id,idempotency_key));
CREATE TABLE IF NOT EXISTS geo_actions (environment TEXT NOT NULL, client_id TEXT NOT NULL, dedup_key TEXT NOT NULL, action_type TEXT NOT NULL, approval_required INTEGER NOT NULL, safe_summary TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(environment,client_id,dedup_key));
